import{_ as e,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"{% ajaxPartial %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Сокращённый синтаксис обновления","slug":"сокращенныи-синтаксис-обновления","link":"#сокращенныи-синтаксис-обновления","children":[]},{"level":2,"title":"Отложенная загрузка фрагментов","slug":"отложенная-загрузка-фрагментов","link":"#отложенная-загрузка-фрагментов","children":[]},{"level":2,"title":"Вызов AJAX-обработчиков","slug":"вызов-ajax-обработчиков","link":"#вызов-ajax-обработчиков","children":[{"level":3,"title":"Захватывающий жизненный цикл","slug":"захватывающии-жизненныи-цикл","link":"#захватывающии-жизненныи-цикл","children":[]}]}],"relativePath":"3.x/ru/markup/tag/ajax-partial.md","filePath":"3.x/ru/markup/tag/ajax-partial.md"}'),i={name:"3.x/ru/markup/tag/ajax-partial.md"};function r(k,a,d,g,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"{% ajaxPartial %}",-1)),s(p),a[1]||(a[1]=u(`<div class="custom-block aside"><p>Этот тег расширяет <a href="./partial.html"><code>{% partial %}</code> Twig-тег</a>.</p></div><p>Тег <code>{% ajaxPartial %}</code> рендерит содержимое фрагмента на странице и включает поддержку <a href="./../../cms/ajax/introduction.html">AJAX-обработчиков</a>, самообновления и сокращённого синтаксиса обновления. Это обычно называется самообновляющимся фрагментом.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Содержимое фрагмента оборачивается определённым HTML-тегом только при первой загрузке. Последующие обновления фрагмента через AJAX не включают тег-обёртку.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-ajax-partial</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    ... Contents go here ...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="сокращенныи-синтаксис-обновления"><a href="#сокращенныи-синтаксис-обновления" class="header-anchor">#</a> Сокращённый синтаксис обновления</h2><p>При использовании AJAX-фрагмента вам больше не нужно указывать селектор для его обновления. Просто передайте <code>true</code> в <a href="./../../cms/ajax/attributes-api.html">API атрибутов данных</a> при использовании атрибута <code>data-request-update</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefresh<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ contact-form: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Refresh
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы также можете обновить фрагмент изнутри, используя <code>_self</code> в качестве имени фрагмента.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefresh<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Refresh
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы также можете передать символ <code>^</code> для добавления в начало и символ <code>@</code> для добавления в конец контейнера вместо замены его содержимого.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onRefresh<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: &#39;@&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Append
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="отложенная-загрузка-фрагментов"><a href="#отложенная-загрузка-фрагментов" class="header-anchor">#</a> Отложенная загрузка фрагментов</h2><p>Тег <code>{% ajaxPartial %}</code> принимает атрибут <code>lazy</code>, который откладывает рендеринг содержимого до загрузки страницы. В следующем примере фрагмент <strong>posts</strong> будет обновлён после завершения загрузки страницы.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span> lazy <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Атрибуты <code>lazy body</code> позволяют указать начальное содержимое перед загрузкой, за которым следует тег <code>{% endpartial %}</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span> lazy body <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Loading posts...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Важно отметить, что тег <code>{% ajaxPartial lazy %}</code> не рендерит фрагмент немедленно. Вместо этого он выводит начальное содержимое, включающее атрибут данных <code>data-auto-submit</code>, используемый <a href="./../../cms/features/polling.html">запросами опроса</a>. Этот атрибут выполняет AJAX-запрос для загрузки содержимого фрагмента после загрузки страницы. Атрибут не включается в последующие обновления фрагмента, чтобы предотвратить бесконечный цикл.</p><p>Вот как это будет выглядеть в браузере при первой загрузке страницы:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-auto-submit</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Loading posts...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>Не включайте приведённую выше разметку в свой фрагмент. Тег <code>{% ajaxPartial lazy %}</code> включит её автоматически.</p></div><h2 id="вызов-ajax-обработчиков"><a href="#вызов-ajax-обработчиков" class="header-anchor">#</a> Вызов AJAX-обработчиков</h2><p>При вызове AJAX-обработчика из AJAX-фрагмента запускается захватывающий жизненный цикл страницы (см. ниже), который обеспечивает использование AJAX-обработчиков в запрашиваемых фрагментах.</p><p>Следующий пример показывает, как отправить простую контактную форму с помощью самообновляющегося фрагмента.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Self Updating Partial</span>&quot;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;submitted&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> submitted <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Thank you for contacting us!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Submit
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Фрагменты, использующие <a href="./../../cms/themes/components.html">CMS-компоненты</a>, также имеют доступ к их AJAX-обработчикам.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">contactForm</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contactForm::onSubmit<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Submit
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><h3 id="захватывающии-жизненныи-цикл"><a href="#захватывающии-жизненныи-цикл" class="header-anchor">#</a> Захватывающий жизненный цикл</h3><p>При вызове обработчика из AJAX-фрагмента запускается другой жизненный цикл, называемый захватывающим жизненным циклом. Захватывающий жизненный цикл рендерит всю страницу, однако содержимое рендерится «в пустоту». Таким образом, страница инициализируется полностью, включая все используемые фрагменты и AJAX-обработчики.</p><p>Поскольку это считается полным рендером страницы, это может означать, что <a href="./../../extend/cms-components.html">метод компонента</a> <code>onRun</code> вызывается при использовании обработчика AJAX-фрагмента. Вы можете использовать <a href="./../../extend/services/request-input.html">вспомогательный метод</a> <code>Request::ajax()</code>, чтобы определить, является ли запрос результатом AJAX-запроса.</p>`,30))])}const x=e(i,[["render",r]]);export{q as __pageData,x as default};
